const e=$input.first().json;
const parar=motivo=>[{json:{status:'REVISAO',motivo}}];
const ler=nome=>JSON.parse(e[nome]);
const dia=v=>typeof v==='string' && /^\d{4}-\d{2}-\d{2}$/.test(v) && Number.isFinite(Date.parse(v+'T00:00:00Z')) && new Date(v+'T00:00:00Z').toISOString().slice(0,10)===v;
try {
 if(e.projeto==='planejador') {
  const eventos=ler('eventos'), tarefas=ler('tarefas');
  if(e.fonte_disponivel!==true) return parar('FONTE_INDISPONIVEL');
  if(!Array.isArray(eventos)||!Array.isArray(tarefas)||!dia(e.data_alvo)) return parar('ENTRADA_INVALIDA');
  for(const x of eventos) if(!x.evento_id||!x.titulo||!Number.isFinite(Date.parse(x.inicio))||!Number.isFinite(Date.parse(x.fim))||Date.parse(x.fim)<=Date.parse(x.inicio)) return parar('EVENTO_INVALIDO');
  const compromissos=eventos.filter(x=>x.inicio.slice(0,10)===e.data_alvo && x.estado!=='cancelado').sort((a,b)=>Date.parse(a.inicio)-Date.parse(b.inicio));
  const conflitos=[];
  for(let i=0;i<compromissos.length;i++) for(let j=i+1;j<compromissos.length;j++) {
    const a=compromissos[i],b=compromissos[j]; const inicio=Math.max(Date.parse(a.inicio),Date.parse(b.inicio)),fim=Math.min(Date.parse(a.fim),Date.parse(b.fim));
    if(inicio<fim) conflitos.push({ids:[a.evento_id,b.evento_id],inicio:new Date(inicio).toISOString(),fim:new Date(fim).toISOString()});
  }
  const lacunas=tarefas.filter(x=>!x.id||!x.titulo||!dia(x.prazo)||!['aberta','em andamento','concluída'].includes(x.estado)||!['baixa','média','alta'].includes(x.importancia)).map(x=>x.id||'SEM_ID');
  const peso={alta:0,'média':1,baixa:2};
  const prioridades=tarefas.filter(x=>!lacunas.includes(x.id)&&x.estado!=='concluída').sort((a,b)=>a.prazo.localeCompare(b.prazo)||peso[a.importancia]-peso[b.importancia]||a.id.localeCompare(b.id)).slice(0,3);
  return [{json:{status:'OK',compromissos,prioridades,conflitos,lacunas,resumo:'Compromissos: '+compromissos.length+'; prioridades: '+prioridades.map(x=>x.id).join(', ')+'; conflitos: '+conflitos.length+'; lacunas: '+lacunas.join(', ')}}];
 }
 if(e.projeto==='reuniao') {
  const registros=ler('registros'), evento=ler('evento');
  if(!Array.isArray(registros)||!evento.evento_id) return parar('ENTRADA_INVALIDA');
  const fontes=registros.filter(x=>x.evento_id===evento.evento_id);
  if(fontes.some(x=>!x.fonte_id)) return parar('FONTE_SEM_ID');
  const lacunas=fontes.filter(x=>!String(x.observacao||'').trim()).map(x=>x.fonte_id);
  return [{json:{status:fontes.length?'OK':'SEM_FONTES',contexto:evento,fontes,fatos:fontes.filter(x=>!lacunas.includes(x.fonte_id)).map(x=>({texto:x.observacao,fonte_id:x.fonte_id})),perguntas:['Quais informações precisam de confirmação?'],lacunas,resumo:fontes.length+' registros relacionados por identificador.'}}];
 }
 if(e.projeto==='relatorio') {
  const registros=ler('registros');
  if(!Array.isArray(registros)||!dia(e.inicio)||!dia(e.fim)||e.fim<=e.inicio) return parar('PERIODO_INVALIDO');
  const grupos={}; let total=0,contagem=0;
  for(const x of registros) {
    if(!dia(x.data)) return parar('DATA_INVALIDA');
    if(x.data<e.inicio||x.data>=e.fim) continue;
    if(!x.registro_id||!x.categoria||String(x.quantidade).trim()===''||!Number.isFinite(Number(x.quantidade))) return parar('REGISTRO_INVALIDO');
    const q=Number(x.quantidade),g=grupos[x.categoria]||{categoria:x.categoria,quantidade:0,registros:0};
    g.quantidade+=q;g.registros++;grupos[x.categoria]=g;total+=q;contagem++;
  }
  return [{json:{status:contagem?'OK':'VAZIO',tabela:Object.values(grupos),total,registros:contagem,resumo:'Foram registrados '+contagem+' itens, com quantidade total '+total+'. Causas não foram avaliadas.'}}];
 }
 return parar('PROJETO_DESCONHECIDO');
} catch { return parar('JSON_INVALIDO'); }
